20	import PointerPath from './PointerPath';
21	import * as graphic from '../../util/graphic';
22	import { setStatesStylesFromModel, toggleHoverEmphasis } from '../../util/states';
23	import {createTextStyle, setLabelValueAnimation, animateLabelValue} from '../../label/labelStyle';
24	import ChartView from '../../view/Chart';
25	import {parsePercent, round, linearMap} from '../../util/number';
26	import GaugeSeriesModel, { GaugeDataItemOption } from './GaugeSeries';
27	import GlobalModel from '../../model/Global';
28	import ExtensionAPI from '../../core/ExtensionAPI';
29	import { ColorString, ECElement } from '../../util/types';
30	import SeriesData from '../../data/SeriesData';
31	import Sausage from '../../util/shape/sausage';
32	import {createSymbol} from '../../util/symbol';
33	import ZRImage from 'zrender/src/graphic/Image';
34	import { extend, isFunction, isString, isNumber, each } from 'zrender/src/core/util';
35	import {setCommonECData} from '../../util/innerStore';
36	import { normalizeArcAngles } from 'zrender/src/core/PathProxy';
