577	    _renderAnchor(
578	        seriesModel: GaugeSeriesModel,
579	        posInfo: PosInfo
580	    ) {
581	        const anchorModel = seriesModel.getModel('anchor');
582	        const showAnchor = anchorModel.get('show');
583	        if (showAnchor) {
584	            const anchorSize = anchorModel.get('size');
585	            const anchorType = anchorModel.get('icon');
586	            const offsetCenter = anchorModel.get('offsetCenter');
587	            const anchorKeepAspect = anchorModel.get('keepAspect');
588	            const anchor = createSymbol(
589	                anchorType,
590	                posInfo.cx - anchorSize / 2 + parsePercent(offsetCenter[0], posInfo.r),
591	                posInfo.cy - anchorSize / 2 + parsePercent(offsetCenter[1], posInfo.r),
592	                anchorSize,
593	                anchorSize,
594	                null,
595	                anchorKeepAspect
596	            ) as graphic.Path;
597	            anchor.z2 = anchorModel.get('showAbove') ? 1 : 0;
598	            anchor.setStyle(anchorModel.getModel('itemStyle').getItemStyle());
599	            this.group.add(anchor);
600	        }
601	    }
602	
603	    _renderTitleAndDetail(
604	        seriesModel: GaugeSeriesModel,
605	        ecModel: GlobalModel,
606	        api: ExtensionAPI,
607	        getColor: (percent: number) => ColorString,
608	        posInfo: PosInfo
609	    ) {
610	        const data = seriesModel.getData();
611	        const valueDim = data.mapDimension('value');
612	        const minVal = +seriesModel.get('min');
613	        const maxVal = +seriesModel.get('max');
614	
615	        const contentGroup = new graphic.Group();
616	
617	        const newTitleEls: graphic.Text[] = [];
618	        const newDetailEls: graphic.Text[] = [];
619	        const hasAnimation = seriesModel.isAnimationEnabled();
620	
621	        const showPointerAbove = seriesModel.get(['pointer', 'showAbove']);
622	
623	        data.diff(this._data)
624	            .add((idx) => {
625	                newTitleEls[idx] = new graphic.Text({
626	                    silent: true
627	                });
628	                newDetailEls[idx] = new graphic.Text({
629	                    silent: true
630	                });
631	            })
632	            .update((idx, oldIdx) => {
633	                newTitleEls[idx] = this._titleEls[oldIdx];
634	                newDetailEls[idx] = this._detailEls[oldIdx];
635	            })
636	            .execute();
637	
638	        data.each(function (idx) {
639	            const itemModel = data.getItemModel<GaugeDataItemOption>(idx);
640	            const value = data.get(valueDim, idx) as number;
641	            const itemGroup = new graphic.Group();
642	            const autoColor = getColor(
643	                linearMap(value, [minVal, maxVal], [0, 1], true)
644	            );
645	
646	            const itemTitleModel = itemModel.getModel('title');
647	            if (itemTitleModel.get('show')) {
648	                const titleOffsetCenter = itemTitleModel.get('offsetCenter');
