import { EChartsType } from '@/src/echarts';
import { createChart } from '../../test/ut/core/utHelper';

// progress.itemStyle.color: 'auto' should resolve to the color of the
// axisLine segment at the current value.
describe('gauge progress color auto', function () {
    let chart: EChartsType;

    function getProgressFill(): unknown {
        const view = (chart as any)._chartsViews[0];
        return view._progressEls[0].style.fill;
    }

    afterEach(function () {
        chart.dispose();
    });

    it('resolves auto to the axisLine segment color at the value', function () {
        chart = createChart();
        chart.setOption({
            animation: false,
            series: {
                type: 'gauge',
                min: 0,
                max: 100,
                axisLine: {
                    lineStyle: {
                        color: [[0.3, 'red'], [0.7, 'green'], [1, 'blue']]
                    }
                },
                progress: {
                    show: true,
                    itemStyle: {
                        color: 'auto'
                    }
                },
                data: [{ value: 50 }]
            }
        });
        expect(getProgressFill()).toEqual('green');

        chart.setOption({
            series: {
                type: 'gauge',
                data: [{ value: 10 }]
            }
        });
        expect(getProgressFill()).toEqual('red');
    });

    it('keeps the series visual color when color is not auto', function () {
        chart = createChart();
        chart.setOption({
            animation: false,
            color: ['#123456'],
            series: {
                type: 'gauge',
                min: 0,
                max: 100,
                progress: {
                    show: true
                },
                data: [{ value: 50 }]
            }
        });
        expect(getProgressFill()).toEqual('#123456');
    });
});
